          "title": "會考高頻素養應用題：速率追趕問題",
          "question": "小明以每小時 4 公里的速率由學校出發步行回家。出發 30 分鐘後，小華發現小明遺落了水壺，立刻以每小時 12 公里的速率騎自行車從學校沿相同路線追趕。求小華出發幾分鐘後可以追上小明？",
          "keyIdea": "設小華騎車出發後 $t$ 小時追上小明。小華追上時，兩人行走的總距離相等。注意時間單位一致性：30 分鐘 $= 0.5$ 小時。",
