        "廣義第 $n$ 項與第 $m$ 項關係：$a_n = a_m + (n - m)d$",
        "等差中項公式：若 $a, b, c$ 成等差數列，則 $b = \\frac{a + c}{2}$，即 $2b = a + c$",
