        "【第 $n$ 項正負轉折點求法】：若數列為遞減（$d < 0$），求首個負數項時，令 $a_n < 0 \\implies a_1 + (n-1)d < 0$ 求解不等式；求總和最大值時，加到最後一個正數項為止。"
