          "question": "在 $\\triangle ABC$ 中，$D, E$ 分別在 $\\overline{AB}, \\overline{AC}$ 上，且 $\\overline{DE} \\parallel \\overline{BC}$。已知 $\\overline{AD} = 4, \\overline{DB} = 6$。若 $\\triangle ABC$ 面積為 $75$，求：① $\\triangle ADE$ 面積；② 四邊形 $DBCE$ 面積。",
          "keyIdea": "先求小三角形與大三角形的邊長比，再平方得出面積比，最後利用全部面積減小三角形求四邊形面積。",
